import { copyFileSync, mkdirSync, readdirSync } from "node:fs";

// tsc already wrote the JavaScript into dist/; add the static entry files next to it.
const demo = new URL("../", import.meta.url);
const dist = new URL("dist/", demo);
mkdirSync(dist, { recursive: true });
for (const file of ["index.html", "styles.css"]) {
  copyFileSync(new URL(file, demo), new URL(file, dist));
}

// Sample parity reports are generated by the .NET tests (SampleReportTests) and committed.
mkdirSync(new URL("samples/", dist), { recursive: true });
for (const file of readdirSync(new URL("samples/", demo))) {
  copyFileSync(new URL(`samples/${file}`, demo), new URL(`samples/${file}`, dist));
}
